flow_stack = {}
per_message_verifiers = {}
CONCURRENT_PREFIX = '__concurrent'


def set_per_message_verifier(*list_of_message_verifiers):
    global per_message_verifiers
    for item in list_of_message_verifiers:
        [message_optional_index, verifier] = [i.strip() for i in item.split(':')]
        message_with_index_list = message_optional_index.split('_')
        message = message_with_index_list[0].strip()
        assert message_exists(message), 'Message: {} is not correct 3GPP name'.format(message)
        per_message_verifiers[message_optional_index] = verifier
    print('Currently assigned verifiers')
    print(pprint.pformat(per_message_verifiers))


def set_per_concurrent_message_verifier(*list_of_message_verifiers):
    global per_message_verifiers
    for item in list_of_message_verifiers:
        [protocol_with_message_name, verifier] = [i.strip() for i in item.split(':')]
        message = protocol_with_message_name.split('_')[1].strip()
        assert message_exists(message), 'Message: {} is not correct 3GPP name'.format(message)
        per_message_verifiers[protocol_with_message_name] = verifier
    print('Currently assigned verifiers')
    print(pprint.pformat(per_message_verifiers))


def clear_per_message_verifier(*list_of_messages_to_clear):
    global per_message_verifiers
    for item in list_of_messages_to_clear:
        item = item.strip()
        message_with_index_list = item.split('_')
        message = message_with_index_list[0]
        assert message_exists(message), 'Message: {} is not correct 3GPP name'.format(message)
        if item in per_message_verifiers:
            del per_message_verifiers[item]
            print('Removed verifier for: {}'.format(item))
    print('Currently assigned verifiers')
    print(pprint.pformat(per_message_verifiers))


def clear_per_concurrent_message_verifier(*list_of_messages_to_clear):
    global per_message_verifiers
    for protocol_with_message_name in list_of_messages_to_clear:
        protocol_with_message_name = protocol_with_message_name.strip()
        message = protocol_with_message_name.split('_')[1]
        assert message_exists(message), 'Message: {} is not correct 3GPP name'.format(message)
        if protocol_with_message_name in per_message_verifiers:
            del per_message_verifiers[protocol_with_message_name]
            print('Removed verifier for: {}'.format(protocol_with_message_name))
    print('Currently assigned verifiers')
    print(pprint.pformat(per_message_verifiers))


def clear_all_verifiers():
    global per_message_verifiers
    per_message_verifiers = {}


def _append_to_stack(keyword, flow):
    print('Flow saved: {} under keyword:\n{}'.format(flow, keyword))
    flow_list = flow_stack.setdefault(keyword, [])
    if flow in flow_list:
        print('The exact same flow cannot be reused under the same keyword\n'
              'Removing old flow: {} from list'.format(flow))
        flow_list.remove(flow)
    if len(flow_list):
        print('Flow added to list which already has {} expects'.format(len(flow_list)))
    flow_list.append(flow)


def _get_flows_from_stack(keyword):
    assert keyword in flow_stack
    return flow_stack[keyword]


def clear_flow_stack():
    global flow_stack
    flow_stack = {}


register_listener_end_test_action(clear_flow_stack)

set_mandatory_kwargs = ['device']
get_mandatory_kwargs = ['device']
MSG_MULTIPLIER = '*'
AVAILABLE_OPTIONS = {
    'timeout': re.compile(r'(\d+)')
}


def _check_kwargs(kwargs, mandatory):
    for m_k in mandatory:
        assert m_k in kwargs, '{} is mandatory kwarg'.format(m_k)


def _create_flow_alias(device, message_aliases, protocol):
    return "{device_alias}_{protocol}_{messages}".format(device_alias=device, protocol=protocol,
                                                         messages="_".join(message_aliases))


def _create_message_alias(messaging_line_definition, all_flow_messages, occurrence=1):
    alias_name = re.search(r'^(?:\S+_)?(\S+)', messaging_line_definition).group(1)
    if all_flow_messages.count(messaging_line_definition) > 1:
        alias_name = '{}_{}'.format(alias_name, occurrence)
    return alias_name


def _get_protocol_by_device(device):
    mapping = {'AMF': 'NGAP', 'gNB': 'XNAP', 'MME': 'S1AP', 'eNB': 'X2AP'}
    for dev in mapping.keys():
        if re.search(dev.lower(), str(device).lower()):
            print('Mapped device: {} to protocol: {}'.format(device, mapping[dev]))
            return mapping[dev]
    print('Could not find protocol for device: {}.\nAvailable mapping: {}\n'
          'Consider specifying protocol directly in keyword kwargs'.format(device, pprint.pformat(mapping)))
    return None


def _get_messages_from_procedure(device_alias, procedure_name, protocol):
    if protocol is None:
        protocol = _get_protocol_by_device(device_alias)
    assert protocol is not None, \
        'Protocol for procedure: {} not found, please specify protocol'.format(procedure_name)
    flow_memory = protocols_flows[protocol]
    proc_names = [p.strip() for p in procedure_name.split(',')]
    extracted_proc_names = []
    for proc in proc_names:
        proc_with_multiple = re.search(r'^(\d+)\*(.*)', proc)
        if proc_with_multiple:
            multiplier = int(proc_with_multiple.group(1))
            proc_found = proc_with_multiple.group(2)
            procs = [proc_found] * multiplier
        else:
            procs = [proc]
        extracted_proc_names.extend(procs)
    wanted_messages = []
    for proc_name in extracted_proc_names:
        _wanted_messages = flow_memory[proc_name]
        for w in _wanted_messages:
            msg = "{}_{}".format(protocol, w)
            wanted_messages.append(msg)
    return wanted_messages


def _extract_to_multiple_messages(message_with_multiplier):
    msg_with_multiple = re.search(r'^(\d+)\*(.*)', message_with_multiplier)
    if msg_with_multiple:
        multiplier = int(msg_with_multiple.group(1))
        msg = msg_with_multiple.group(2)
        msgs = [msg] * multiplier
    else:
        msgs = [message_with_multiplier]
    return msgs


def _get_index_of_the_same_message(all_messages, current_message, loop_index):
    if all_messages.count(current_message) == 1:
        return 1
    else:
        msgs_before_item = all_messages[:loop_index + 1]
        msg_idx = msgs_before_item.count(current_message)
        return msg_idx


def _get_flow_options(keyword_name_with_options, concurrent=False):
    keyword_name_with_options = str(keyword_name_with_options)
    options = CONSTANT_HEADERS['expect' if concurrent is False else 'expect_concurrent']['regexp']\
        .search(keyword_name_with_options).group(1)
    received_options = {}
    if options != ':':
        options = re.findall(r'\[(.*?)\]', options)[0]
        option_list = [o.strip() for o in options.split(';')]
        for opt in option_list:
            opt_name, opt_value = opt.split('=')
            if opt_name in AVAILABLE_OPTIONS:
                opt_value_matching = AVAILABLE_OPTIONS[opt_name].search(opt)
                if opt_value_matching:
                    received_options[opt_name] = opt_value_matching.group(1)
                    print('Found option: {}={}'.format(opt_name, received_options[opt_name]))
                else:
                    print('Option found: {} but regexp not matching, skip'.format(opt_name))
            else:
                print('Option: {} not found, available: {}'.format(opt_name, list(AVAILABLE_OPTIONS.keys())))
    return received_options


def _extract_duplicated_messages(args, protocol):
    wanted_messages = []
    for arg in args:
        mutliple_messages = [i.strip() for i in arg.strip().split(',')]
        for m_message in mutliple_messages:
            _msgs = _extract_to_multiple_messages(m_message)
            messages_protocol = ["{}_{}".format(protocol, m) for m in _msgs]
            wanted_messages.extend(messages_protocol)
    return wanted_messages


def set_flow(*args, **kwargs):
    last_expect = get_last_expect_keyword(without_library_part=True)
    print('Last expect keyword: {}'.format(last_expect))
    flow_options = _get_flow_options(last_expect, concurrent=False)
    _check_kwargs(kwargs, set_mandatory_kwargs)
    device_alias = kwargs.get('device')
    timeout = kwargs.get('timeout', 60)
    procedure_name = kwargs.get('procedure', None)
    verifier = kwargs.get('verifier', None)
    protocol = kwargs.get('protocol', None)
    if 'timeout' in flow_options:
        timeout = flow_options['timeout']
    expected_messages = []
    if protocol is None:
        protocol = _get_protocol_by_device(device_alias)
    assert protocol is not None, \
        'Protocol for procedure: {} not found, please specify protocol'.format(procedure_name)
    if procedure_name is not None:
        wanted_messages = _get_messages_from_procedure(device_alias, procedure_name, protocol)
    else:
        wanted_messages = _extract_duplicated_messages(args, protocol)
    print('Wanted messages:\n{}'.format(pprint.pformat(wanted_messages)))
    message_aliases = create_message_aliases_from_wanted_messages(wanted_messages)
    wanted_verifiers = create_wanted_verifiers_from_message_aliases(message_aliases, verifier)
    for m_idx, message in enumerate(wanted_messages):
        message_alias = message_aliases[m_idx]
        if wanted_verifiers[m_idx] is None:
            message_line = "{alias}:{protocol_message} as {msg_alias}"\
                .format(alias=device_alias,
                        protocol_message=message,
                        msg_alias=message_alias)
        else:
            message_line = "{alias}:{protocol_message} ({verifier}) as {msg_alias}" \
                .format(alias=device_alias,
                        protocol_message=message,
                        verifier=wanted_verifiers[m_idx],
                        msg_alias=message_alias)
        expected_messages.append(message_line)
    print('Expected message lines in flow:\n{}'.format(pprint.pformat(expected_messages)))
    flow_alias = _create_flow_alias(device_alias, message_aliases, protocol)
    MessageFlow.expect_message_flow(alias=flow_alias, overall_timeout=timeout, awaited_messages=expected_messages)
    _append_to_stack(last_expect, flow_alias)


def _get_user_subsriber_instance():
    try:
        user_message_subscriber_instance = BuiltIn().get_library_instance('ta_messaging.user_message_subscriber')
    except Exception:
        BuiltIn().import_library('ta_messaging.user_message_subscriber')   # needed to benefit from robot part
        user_message_subscriber_instance = BuiltIn().get_library_instance('ta_messaging.user_message_subscriber')
    return user_message_subscriber_instance


def _create_concurrent_flow_alias(message_name, device_alias, occurrences):
    return "{}{}".format(CONCURRENT_PREFIX, "_".join([message_name, device_alias, str(occurrences)]))


def _get_concurrent_flow_params(alias):
    """
    returns message_name, device_alias, occurrences
    """
    alias = re.sub(CONCURRENT_PREFIX, '', alias)
    return alias.split('_')


def set_concurrent_flow(*args, **kwargs):
    user_message_subscriber_instance = _get_user_subsriber_instance()
    last_expect = get_last_expect_keyword(without_library_part=True)
    print('Last expect keyword: {}'.format(last_expect))
    flow_options = _get_flow_options(last_expect, concurrent=True)
    _check_kwargs(kwargs, set_mandatory_kwargs)
    device_alias = kwargs.get('device')
    timeout = kwargs.get('timeout', 60)
    procedure_name = kwargs.get('procedure', None)
    verifier = kwargs.get('verifier', None)
    protocol = kwargs.get('protocol', None)
    if 'timeout' in flow_options:
        timeout = flow_options['timeout']
    if procedure_name is not None:
        wanted_messages = _get_messages_from_procedure(device_alias, procedure_name, protocol)
    else:
        wanted_messages = _extract_duplicated_messages(args, protocol)
    print('Wanted messages:\n{}'.format(pprint.pformat(wanted_messages)))
    unique_wanted_messages = list(set(wanted_messages))
    wanted_verifiers = create_wanted_verifiers_from_message_aliases_for_unique_messages(unique_wanted_messages,
                                                                                        verifier)
    for w_msg in unique_wanted_messages:
        message_name = w_msg.split('_')[1]
        message_number = wanted_messages.count(w_msg)
        user_message_subscriber_instance.user_single_message_subscriber_subscribe(message_name,
                                                                                  timeout=timeout,
                                                                                  msg_num=message_number,
                                                                                  owner_alias=device_alias,
                                                                                  protocol=protocol)
        print('Subscribed for: {} with {} occurrences on device: {} with timeout: {}'
              .format(message_name, message_number, device_alias, timeout))
        if wanted_verifiers[wanted_messages.index(w_msg)] is not None:
            ver = wanted_verifiers[wanted_messages.index(w_msg)]
            user_message_subscriber_instance.\
                user_single_message_subscriber_register_user_verifier(message_type=message_name,
                                                                      verifier=ver,
                                                                      owner_alias=device_alias)
            print('Added verifier: {} for message: {} for owner: {}'.format(ver, message_name, device_alias))
        flow_alias = _create_concurrent_flow_alias(message_name=message_name,
                                                   device_alias=device_alias,
                                                   occurrences=message_number)
    _append_to_stack(last_expect, flow_alias)


def create_wanted_verifiers_from_message_aliases(message_aliases, common_verifier):
    wanted_verifiers = []
    for msg_alias in message_aliases:
        if msg_alias in per_message_verifiers:
            custom_verifier = per_message_verifiers[msg_alias]
        else:
            custom_verifier = common_verifier
        wanted_verifiers.append(custom_verifier)
    return wanted_verifiers


def create_wanted_verifiers_from_message_aliases_for_unique_messages(message_names, common_verifier):
    wanted_verifiers = []
    for msg_alias in message_names:
        if msg_alias in per_message_verifiers:
            custom_verifier = per_message_verifiers[msg_alias]
        else:
            custom_verifier = common_verifier
        wanted_verifiers.append(custom_verifier)
    if not len(wanted_verifiers):
        print('Not found any common or custom verifier to be set')
    return wanted_verifiers


def create_message_aliases_from_wanted_messages(wanted_messages):
    message_aliases = []
    for m_idx, message in enumerate(wanted_messages):
        same_message_index = _get_index_of_the_same_message(wanted_messages, message, m_idx)
        message_alias = _create_message_alias(message,
                                              all_flow_messages=wanted_messages,
                                              occurrence=same_message_index)
        message_aliases.append(message_alias)
    return message_aliases


def get_flow_name(*args, **kwargs):
    _check_kwargs(kwargs, get_mandatory_kwargs)
    device_alias = kwargs.get('device')
    procedure_name = kwargs.get('procedure', None)
    protocol = kwargs.get('protocol', None)
    if protocol is None:
        protocol = _get_protocol_by_device(device_alias)
    assert protocol is not None, \
        'Get flow name: protocol= must be provided.\nShould be removed from message part:\n' \
        'e.g. NR-RRC_RRCSetup -> RRCSetup\n' \
        'and added as kwarg:\ne.g. protocol=NR-RRC\n' \
        'Please adapt your testcase accordingly'
    if procedure_name is not None:
        wanted_messages = _get_messages_from_procedure(device_alias, procedure_name, protocol)
    else:
        wanted_messages = _extract_duplicated_messages(args, protocol)
    message_aliases = create_message_aliases_from_wanted_messages(wanted_messages)
    flow_alias = _create_flow_alias(device_alias, message_aliases, protocol)
    return flow_alias


def get_concurrent_flow_message(*args, **kwargs):
    _check_kwargs(kwargs, get_mandatory_kwargs)
    device_alias = kwargs.get('device')
    procedure_name = kwargs.get('procedure', None)
    protocol = kwargs.get('protocol', None)
    wanted_message = kwargs.get('wanted_message', None)
    wanted_occurrence = int(kwargs.get('wanted_occurrence', 1))
    if protocol is None:
        protocol = _get_protocol_by_device(device_alias)
    assert protocol is not None, \
        'Get flow name: protocol= must be provided.\nShould be removed from message part:\n' \
        'e.g. NR-RRC_RRCSetup -> RRCSetup\n' \
        'and added as kwarg:\ne.g. protocol=NR-RRC\n' \
        'Please adapt your testcase accordingly'
    if procedure_name is not None:
        procedure_messages = _get_messages_from_procedure(device_alias, procedure_name, protocol)
    else:
        procedure_messages = _extract_duplicated_messages(args, protocol)
    assert wanted_message is not None and '_' not in wanted_message,\
        'Must supply wanted_message= kwarg to retrieve message from procedure, it must not contain protocol'
    unique_procedure_messages = list(set(procedure_messages))
    user_message_subscriber_instance = _get_user_subsriber_instance()
    for w_msg in unique_procedure_messages:
        message_name = w_msg.split('_')[1]
        message_number = procedure_messages.count(w_msg)
        if message_name == wanted_message:
            all_messages = \
                user_message_subscriber_instance.get_messages_from_subscriber(message_type=message_name,
                                                                              subscriber_owner_alias=device_alias,
                                                                              occurrences=message_number,
                                                                              parsed=True)
            assert len(all_messages) >= wanted_occurrence, \
                'Found flow for: {} messages, wanted occurrence: {}'.format(len(all_messages), wanted_occurrence)
            return all_messages[wanted_occurrence - 1]

    raise Exception('Could not find required message: {} within started flows for messages: {}'
                    .format(wanted_message, unique_procedure_messages))


