    keyword_name_with_expect = "{}{} {}".format(CONSTANT_HEADERS['expect_concurrent']['prefix'], options, keyword_name)
    assert keyword_name_with_expect in flow_stack, 'Concurrent Flow:\n{} not registered. Available names:\n{}' \
        .format(keyword_name_with_expect, [item for item in list(flow_stack.keys()) if 'CONCURRENT' in item])
